-- 0008_txasm.sql - /txasm landing page + bio cross-link. ADDITIVE. 0000-0007 untouched.
-- Mirrors app/lib/content-defaults.ts (generated by scripts/gen-content-seed.mjs). 0005 is already
-- applied on existing DBs, so the new page ships here as INSERT OR IGNORE, and the bio link is
-- injected with a guarded REPLACE (idempotent: it only runs when the /txasm link is not yet present,
-- so it never double-wraps and never clobbers an unrelated live edit).

-- content_blocks: the /txasm landing page (published).
INSERT OR IGNORE INTO content_blocks (key, kind, title, value, status) VALUES ('page:txasm', 'page', 'Texas Branch of the American Society for Microbiology', '<p>The Texas Branch of the American Society for Microbiology promotes the science of microbiology across Texas through meetings, education, and discussion. Founded in 1941, the branch hosts annual meetings that bring together students and faculty from colleges, universities, and community colleges across the state to share research, mentor young scientists, and teach microbiology.</p><p>Germomics hosted the branch''s website for several years. The branch now has its own home at txasm.org, with the current officers, meeting registration and programs, abstracts, newsletters, and awards.</p><p>Dr. Dustin Edwards, who makes Germomics, serves as an officer and the Archivist of the Texas Branch.</p>', 'published');

-- Link the "Texas Branch of the American Society for Microbiology" mention in the bio to /txasm so
-- the new page is not orphaned. Guarded so re-applying is a no-op.
UPDATE content_blocks
SET value = REPLACE(value, 'Texas Branch of the American Society for Microbiology', '<a href="/txasm">Texas Branch of the American Society for Microbiology</a>'),
    updated_at = datetime('now')
WHERE key = 'page:dustin-edwards' AND value NOT LIKE '%/txasm%';
